import os
import base64
import boto3
from botocore.exceptions import ClientError
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from typing import Optional, Dict

class EnvelopeEncryptionAWS:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id
        self.region = region_name or os.environ.get('AWS_DEFAULT_REGION', 'us-east-1')
        self.kms_client = boto3.client('kms', region_name=self.region)

    def generate_data_key(self) -> Dict[str, bytes]:
        try:
            response = self.kms_client.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec='AES_256'
            )
            return {
                'plaintext_key': response['Plaintext'],
                'encrypted_key': response['CiphertextBlob']
            }
        except ClientError as e:
            raise RuntimeError(f"KMS generate_data_key failed: {e}")

    def encrypt(self, plaintext: bytes) -> Dict[str, str]:
        data_key = self.generate_data_key()
        aesgcm = AESGCM(data_key['plaintext_key'])
        nonce = os.urandom(12)
        ciphertext = aesgcm.encrypt(nonce, plaintext, None)

        return {
            'encrypted_data_key': base64.b64encode(data_key['encrypted_key']).decode('utf-8'),
            'nonce': base64.b64encode(nonce).decode('utf-8'),
            'ciphertext': base64.b64encode(ciphertext).decode('utf-8')
        }

    def decrypt(self, encrypted_data_key: str, nonce: str, ciphertext: str) -> bytes:
        try:
            enc_key = base64.b64decode(encrypted_data_key)
            nonce_bytes = base64.b64decode(nonce)
            ciphertext_bytes = base64.b64decode(ciphertext)

            response = self.kms_client.decrypt(CiphertextBlob=enc_key)
            plaintext_key = response['Plaintext']

            aesgcm = AESGCM(plaintext_key)
            return aesgcm.decrypt(nonce_bytes, ciphertext_bytes, None)
        except ClientError as e:
            raise RuntimeError(f"KMS decrypt failed: {e}")
